pub fn stoi(s: &[u8]) -> Result<i32, ()> {
    let mut i = 0usize; let mut v: i64 = 0; let mut any = false;
    while i < s.len() && matches!(s[i], 0x20|0x09|0x0a|0x0b|0x0c|0x0d) { i += 1; }
