    while i < s.len() && s[i].is_ascii_digit() { any = true; v = v.saturating_mul(10).saturating_add((s[i]-b'0') as i64); i += 1; }
    if !any { return Err(()); }
    let v = if neg { -v } else { v };
    if v < i32::MIN as i64 || v > i32::MAX as i64 { return Err(()); }
    Ok(v as i32)
