use std::hash::{BuildHasher, Hash, Hasher};
use std::time::Instant;

const NB: usize = 32; // neighbourhood
#[derive(Default)] struct Id { s: u64 }
impl Hasher for Id {
    fn finish(&self) -> u64 { self.s }
    fn write(&mut self, b: &[u8]) { let mut h=0xcbf29ce484222325u64; for &x in b { h^=x as u64; h=h.wrapping_mul(0x100000001b3);} self.s=h; }
    fn write_i32(&mut self, i: i32) { self.s = i as u32 as u64; }
}
struct BId;
impl BuildHasher for BId { type Hasher = Id; fn build_hasher(&self) -> Id { Id::default() } }

struct Bucket<K,V> { nb: u32, e: Option<(K,V)> }
impl<K,V> Bucket<K,V> { fn new()->Self{Bucket{nb:0,e:None}} }

struct T<K,V,S=BId> { b: Vec<Bucket<K,V>>, ovf: Vec<(K,V)>, n: usize, mask: usize, hb: S, maxlf: f32 }

impl<K: Hash+Eq, V> T<K,V,BId> {
    fn with_cap(c: usize) -> Self {
        let bc = c.next_power_of_two().max(16);
        let mut b = Vec::with_capacity(bc+NB-1);
        for _ in 0..bc+NB-1 { b.push(Bucket::new()); }
        T{ b, ovf: Vec::new(), n:0, mask: bc-1, hb: BId, maxlf: 0.9 }
    }
    fn bc(&self)->usize{ self.mask+1 }
    fn hash(&self, k:&K)->usize{ let mut s=self.hb.build_hasher(); k.hash(&mut s); (s.finish() as usize) & self.mask }
    fn find(&self, k:&K)->Option<usize>{
        let h=self.hash(k); let mut m=self.b[h].nb;
        while m!=0 { let d=m.trailing_zeros() as usize; let i=h+d;
            if let Some((bk,_))=&self.b[i].e { if bk==k { return Some(i); } }
            m &= m-1; }
        for (j,(bk,_)) in self.ovf.iter().enumerate() { if bk==k { return Some(self.bc()+NB-1+j); } }
        None
    }
    fn insert(&mut self, k:K, v:V)->bool{
        if self.find(&k).is_some(){ return false; }
        if (self.n+1) as f32 > self.bc() as f32 * self.maxlf { self.grow(); }
        self.n+=1; self.place(k,v); true
    }
    fn place(&mut self, k:K, v:V){
        let h=self.hash(&k);
        // linear probe for free slot
        let lim=self.b.len();
        let mut f=h; while f<lim && self.b[f].e.is_some() { f+=1; }
        if f>=lim { self.ovf.push((k,v)); return; }
        // hop back until inside neighbourhood
        while f-h >= NB {
            let mut moved=false;
            let start = f+1-NB;
            for cand in start..f {
                // home of entry at cand
                let ch = { let (ck,_) = self.b[cand].e.as_ref().unwrap(); self.hash(ck) };
                if ch+NB > f && ch<=cand {
                    let e = self.b[cand].e.take().unwrap();
                    self.b[f].e = Some(e);
                    self.b[ch].nb &= !(1u32<<(cand-ch));
                    self.b[ch].nb |= 1u32<<(f-ch);
                    f=cand; moved=true; break;
                }
            }
            if !moved { self.ovf.push((k,v)); return; }
        }
        self.b[f].e=Some((k,v));
        self.b[h].nb |= 1u32<<(f-h);
    }
    fn grow(&mut self){
        let nbc=self.bc()*2;
        let old=std::mem::replace(&mut self.b, { let mut nv=Vec::with_capacity(nbc+NB-1); for _ in 0..nbc+NB-1 { nv.push(Bucket::new()); } nv });
        let oldovf=std::mem::take(&mut self.ovf);
        self.mask=nbc-1;
        for bk in old { if let Some((k,v))=bk.e { self.place(k,v); } }
        for (k,v) in oldovf { self.place(k,v); }
    }
    fn equal_range(&self, k:&K)->(usize,usize){
        match self.find(k){ None=>(self.end(),self.end()), Some(p)=>(p,self.after(p)) }
    }
    fn end(&self)->usize{ self.b.len()+self.ovf.len() }
    fn after(&self, p:usize)->usize{
        let mut i=p+1;
        while i<self.b.len() { if self.b[i].e.is_some(){return i;} i+=1; }
        if self.ovf.is_empty(){ self.end() } else if p<self.b.len() { self.b.len() } else { p+1 }
    }
}

fn main(){
    let n: i32 = std::env::args().nth(1).unwrap().parse().unwrap();
    let t0=Instant::now();
    let mut m=T::with_cap(0);
    for i in 0..n { m.insert(i, i.wrapping_mul(12)); }
    let build=t0.elapsed();
    let (a,b)=m.equal_range(&(n/2));
    let mut c=0; let mut it=a; while it!=b { c+=1; it=m.after(it); }
    println!("{}", c);
    eprintln!("n={} build={:?} len={} bc={} ovf={}", n, build, m.n, m.bc(), m.ovf.len());
}
